import requests
import numpy as np
import time
import os

# Load the coordinates generated by generate_coordinates.py
coordinates = np.load("coordinates.npy")
n = len(coordinates)

print(f"Computing travel times for {n} coordinates ({n*n} total routes)...")
print("Make sure OSRM Docker is running on localhost:5000 before continuing.")

travel_times = np.zeros((n, n))

def get_travel_time(origin, destination):
    """Query local OSRM server for driving time in seconds between two points."""
    lat1, lon1 = origin
    lat2, lon2 = destination
    url = (
        f"http://localhost:5001/route/v1/driving/"
        f"{lon1},{lat1};{lon2},{lat2}?overview=false"
    )
    try:
        r = requests.get(url, timeout=5)
        data = r.json()
        if data.get("code") == "Ok":
            return data["routes"][0]["duration"]  # seconds
        else:
            return 9999  # no route found
    except Exception as e:
        print(f"  Error: {e}")
        return 9999

# Loop through every pair of coordinates
for i in range(n):
    for j in range(n):
        if i == j:
            travel_times[i][j] = 0  # same point = zero time
        else:
            travel_times[i][j] = get_travel_time(
                coordinates[i], coordinates[j]
            )

    # Progress update after each row
    print(f"  Row {i+1}/{n} complete")

    # Small pause to avoid overwhelming OSRM
    time.sleep(0.05)

os.makedirs("img", exist_ok=True)
np.save("travel_times.npy", travel_times)
print(f"\nDone. Saved travel_times.npy  ({n}x{n} matrix)")